def check_concise(tag, full, short):
    """Every number in the short text must appear in the full text."""
    missing = [n for n in NUM.findall(re.sub(r"\bE0\d\d\b", "", short)) if n not in full]   # roll numbers are names, not data
    if missing:
        raise ValueError(f"[CONCISE] {tag}: numbers {missing} are not in the full text")
    return short
